WITNESS = {'k_min': 2, 'k_max': 16, 'n_max': 10000, 's_max': 256}

def Omega(m):
    if m < 1:
        raise ArithmeticError('Omega undefined for m<1')
    total = 0
    d = 2
    while d * d <= m:
        while m % d == 0:
            total += 1
            m //= d
        d += 1
    if m > 1:
        total += 1
    return total

def verify(witness):
    k_min = int(witness['k_min']); k_max = int(witness['k_max'])
    n_max = int(witness['n_max']); s_max = int(witness['s_max'])
    if k_min < 2 or k_max > 16 or n_max < 1 or s_max < 2 or n_max > 100000 or s_max > 100000:
        raise ArithmeticError('witness out of certified envelope')
    for k in range(k_min, k_max + 1):
        base = 2 ** k
        for s in range(2, s_max + 1):
            m = base * s
            if Omega(m) != k + Omega(s):
                raise ArithmeticError('additivity broken k=%d s=%d' % (k, s))
            if not (Omega(m) > k):
                raise ArithmeticError('Omega not > k, k=%d s=%d' % (k, s))
    for k in range(k_min, k_max + 1):
        base = 2 ** k
        for n in range(1, n_max + 1):
            if n <= 2 * base:
                t = 2
            else:
                t = -((-n) // base)
                if t < 2:
                    t = 2
            m = base * t
            if not (n <= m):
                raise ArithmeticError('m<n k=%d n=%d' % (k, n))
            if not (m < n + 2 ** (k + 1)):
                raise ArithmeticError('m too far k=%d n=%d m=%d' % (k, n, m))
            if Omega(m) != k + Omega(t):
                raise ArithmeticError('interval additivity k=%d n=%d' % (k, n))
            if not (Omega(m) >= k + 1):
                raise ArithmeticError('Omega(m) < k+1 k=%d n=%d' % (k, n))

verify(WITNESS)
